                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      <div className="flex flex-wrap gap-2 pt-4">
        {Object.values(TRACEABILITY_LABELS).map(label => (
          <Badge key={label} variant="outline" className="text-[8px] border-white/10 text-white/30">
            {label}
          </Badge>
        ))}
      </div>
    </div>
  );
}

