import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { Search, ArrowLeft, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { useState } from "react";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/app/search")({
  component: SearchPage,
});

function SearchPage() {
  const navigate = useNavigate();
  const [query, setQuery] = useState("");

  const categories = ["Processo", "Pessoa", "Documento", "Entrevista", "Fonte", "Quesito"];

  return (
    <div className="min-h-[100dvh] veritas-hero-gradient p-6 text-white">
      <div className="flex items-center gap-4 mb-6">
        <Button 
          variant="ghost" 
          size="icon" 
          className="text-veritas-silver hover:bg-white/5"
          onClick={() => navigate({ to: "/app" })}
        >
          <ArrowLeft className="w-6 h-6" />
        </Button>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-veritas-silver/40" />
          <Input 
            autoFocus
            placeholder="Pesquisar..." 
            className="pl-11 bg-veritas-graphite/40 border-white/5 focus-visible:ring-veritas-electric/20"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          {query && (
            <button className="absolute right-4 top-1/2 -translate-y-1/2" onClick={() => setQuery("")}>
              <X className="w-4 h-4 text-veritas-silver/40" />
            </button>
          )}
        </div>
      </div>

      <div className="space-y-4">
        <h3 className="text-[10px] font-bold text-white/20 uppercase tracking-widest">Categorias</h3>
        <div className="flex flex-wrap gap-2">
          {categories.map((cat) => (
            <Button key={cat} variant="outline" className="rounded-full bg-white/5 border-white/5 text-xs h-8">
              {cat}
            </Button>
          ))}
        </div>
        <div className="mt-8 text-center text-veritas-silver/20 text-sm">
          Use a busca para localizar rapidamente qualquer informação técnica ou processual em seus casos.
        </div>
      </div>
    </div>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { BottomNavigation } from "@/components/veritas/BottomNavigation";
import { ChevronLeft, FileText, Info, ShieldCheck, Layers } from "lucide-react";
import { isTemplateId } from "@/features/documents/template-ids";
import { getTemplateById } from "@/features/documents/mock-templates";
import { getDocumentTypeById } from "@/features/documents/document-types";
import { TemplateStatusBadge } from "@/components/veritas/templates/TemplateStatusBadge";
import { Button } from "@/components/ui/button";

export const Route = createFileRoute("/app/templates/$templateId")({
  component: TemplateDetailPage,
});

function TemplateDetailPage() {
  const { templateId } = Route.useParams();

  if (!isTemplateId(templateId)) {
    return <NotFoundState />;
  }

  const template = getTemplateById(templateId);

  if (!template) {
    return <NotFoundState />;
  }

  return (
    <div className="min-h-screen bg-[#0A0D14] pb-24 text-white">
      <div className="fixed inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-[0.03] pointer-events-none" />

      <header className="sticky top-0 z-50 px-6 pt-[calc(1.5rem+env(safe-area-inset-top))] pb-6 bg-[#0A0D14]/80 backdrop-blur-xl border-b border-white/5">
        <div className="flex items-center gap-4 mb-4">
          <Link 
            to="/app/templates" 
            className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-white/40 hover:text-white transition-colors"
          >
            <ChevronLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-lg font-bold tracking-tight line-clamp-1">{template.name}</h1>
            <p className="text-white/40 text-[10px] uppercase tracking-widest font-bold">Detalhes do Modelo</p>
          </div>
        </div>
      </header>

      <main className="p-6 space-y-6 relative">
        {/* Info Card */}
        <div className="p-6 rounded-3xl bg-white/5 border border-white/5 space-y-6">
          <div className="flex items-start justify-between">
            <div className="w-14 h-14 rounded-2xl bg-veritas-electric/10 border border-veritas-electric/20 flex items-center justify-center">
              <FileText className="w-7 h-7 text-veritas-electric" />
            </div>
            <TemplateStatusBadge status={template.status} />
          </div>

          <div className="space-y-2">
            <h2 className="text-xl font-bold">{template.name}</h2>
            <p className="text-sm text-veritas-silver/60 leading-relaxed">
              {template.description}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-3 pt-2">
            <div className="p-3 rounded-2xl bg-white/5 border border-white/5">
              <p className="text-[10px] text-white/30 uppercase tracking-widest font-bold mb-1">Escopo</p>
              <p className="text-xs font-bold capitalize">
                {template.scope === 'multiprofessional' ? 'Multiprofissional' : 'Geral'}
              </p>
            </div>
            <div className="p-3 rounded-2xl bg-white/5 border border-white/5">
              <p className="text-[10px] text-white/30 uppercase tracking-widest font-bold mb-1">Origem</p>
              <p className="text-xs font-bold">
                {template.id === 'veritas-multiprofessional' ? 'Estrutura multiprofissional Veritas' : 'Estrutura documental Veritas'}
              </p>
            </div>
          </div>
        </div>

        {/* Modalidades Compatíveis */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
            <Layers className="w-4 h-4 text-veritas-violet" />
            <h3 className="text-xs font-bold text-white uppercase tracking-widest">Modalidades Compatíveis</h3>
          </div>
          <div className="space-y-2">
            {template.supportedDocumentTypes.map((docTypeId) => {
              const docType = getDocumentTypeById(docTypeId);
              return (
                <div key={docTypeId} className="p-4 rounded-2xl bg-white/5 border border-white/5 flex items-center justify-between">
                  <span className="text-sm font-medium">{docType?.label || docTypeId}</span>
                  <ShieldCheck className="w-4 h-4 text-veritas-violet/40" />
                </div>
              );
            })}
          </div>
        </section>

        {/* Informação Adicional */}
        <div className="p-4 rounded-2xl bg-veritas-electric/5 border border-veritas-electric/10 flex gap-3">
          <Info className="w-5 h-5 text-veritas-electric shrink-0 mt-0.5" />
          <div>
            <p className="text-xs font-bold text-white mb-1">Modelo de Referência</p>
            <p className="text-[11px] text-white/40 leading-relaxed">
              Este é um modelo de referência documental do Veritas, validado para conformidade com normas profissionais vigentes.
            </p>
          </div>
        </div>
      </main>

      <BottomNavigation />
    </div>
  );
}

function NotFoundState() {
  return (
    <div className="min-h-screen bg-[#0A0D14] flex flex-col text-white p-6">
      <div className="flex-1 flex flex-col items-center justify-center space-y-6 text-center">
        <div className="w-20 h-20 rounded-3xl bg-red-500/10 border border-red-500/20 flex items-center justify-center">
          <FileText className="w-10 h-10 text-red-500/40" />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-bold">Modelo não encontrado</h2>
          <p className="text-sm text-white/40 px-8">
            A estrutura documental solicitada não existe ou foi removida da biblioteca.
          </p>
        </div>
        <Button variant="outline" className="border-white/10 bg-white/5" asChild>
          <Link to="/app/templates">Voltar para Biblioteca</Link>
        </Button>
      </div>
      <BottomNavigation />
    </div>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { BottomNavigation } from "@/components/veritas/BottomNavigation";
import { ChevronLeft } from "lucide-react";
import { getActiveTemplates } from "@/features/documents/mock-templates";
import { TemplateCard } from "@/components/veritas/templates/TemplateCard";

export const Route = createFileRoute("/app/templates/")({
  component: TemplatesListPage,
});

function TemplatesListPage() {
  const templates = getActiveTemplates();

  const generalTemplates = templates.filter((t) => t.scope === "general");
  const multiprofessionalTemplates = templates.filter((t) => t.scope === "multiprofessional");

  return (
    <div className="min-h-screen bg-[#0A0D14] pb-24 text-white">
      <div className="fixed inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-[0.03] pointer-events-none" />

      <header className="sticky top-0 z-50 px-6 pt-[calc(1.5rem+env(safe-area-inset-top))] pb-6 bg-[#0A0D14]/80 backdrop-blur-xl border-b border-white/5">
        <div className="flex items-center gap-4 mb-4">
          <Link 
            to="/app" 
            className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-white/40 hover:text-white transition-colors"
          >
            <ChevronLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-xl font-bold tracking-tight">Biblioteca de Modelos</h1>
            <p className="text-white/40 text-[10px] uppercase tracking-widest font-bold">Estruturas documentais disponíveis</p>
          </div>
        </div>
      </header>

      <main className="p-6 space-y-8 relative">
        {generalTemplates.length > 0 && (
          <section className="space-y-4">
            <h2 className="text-xs font-bold text-veritas-electric uppercase tracking-widest px-1">Geral</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {generalTemplates.map((template) => (
                <TemplateCard key={template.id} template={template} />
              ))}
            </div>
          </section>
        )}

        {multiprofessionalTemplates.length > 0 && (
          <section className="space-y-4">
            <h2 className="text-xs font-bold text-veritas-violet uppercase tracking-widest px-1">Multiprofissional</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {multiprofessionalTemplates.map((template) => (
                <TemplateCard key={template.id} template={template} />
              ))}
            </div>
          </section>
        )}
      </main>

      <BottomNavigation />
    </div>
  );
}

import { createFileRoute, Outlet } from "@tanstack/react-router";
import { CaseWorkflowProvider } from "@/features/cases/CaseWorkflowProvider";
import { CaseDossierProvider } from "@/features/dossier/CaseDossierProvider";

export const Route = createFileRoute("/app")({
	component: AppLayout,
});

function AppLayout() {
	return (
		<CaseWorkflowProvider>
			<CaseDossierProvider>
				<Outlet />
			</CaseDossierProvider>
		</CaseWorkflowProvider>
	);
}

import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ArrowLeft, ShieldCheck, Mail, CheckCircle2 } from "lucide-react";

export const Route = createFileRoute("/forgot-password")({
  component: ForgotPasswordPage,
});

function ForgotPasswordPage() {
  const [isSuccess, setIsSuccess] = useState(false);
  const [email, setEmail] = useState("");
  const navigate = useNavigate();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      setIsSuccess(true);
    }
  };

  return (
    <div className="min-h-screen veritas-hero-gradient flex flex-col p-6 overflow-hidden relative">
      {/* Background Decorative Elements */}
      <div className="absolute top-[-10%] right-[-10%] w-64 h-64 bg-veritas-electric/5 rounded-full blur-3xl" />
      <div className="absolute bottom-[-5%] left-[-5%] w-80 h-80 bg-veritas-violet/5 rounded-full blur-3xl" />

      {/* Back Button */}
      <div className="relative z-10 mb-8 animate-fade-in-up" style={{ animationDelay: '0.1s' }}>
        <Button 
          variant="ghost" 
          size="icon" 
          onClick={() => navigate({ to: "/login" })}
          className="text-veritas-silver hover:text-veritas-electric hover:bg-white/5 transition-colors rounded-full"
        >
          <ArrowLeft className="h-6 w-6" />
        </Button>
      </div>

      <main className="flex-1 flex flex-col max-w-md mx-auto w-full relative z-10">
        {!isSuccess ? (
          <div className="animate-fade-in-up space-y-8" style={{ animationDelay: '0.2s' }}>
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center relative group">
                <div className="absolute inset-0 bg-veritas-electric/20 rounded-2xl blur-md opacity-0 group-hover:opacity-100 transition-opacity" />
                <ShieldCheck className="h-8 w-8 text-veritas-electric relative z-10" />
              </div>

              <div className="space-y-2">
                <h1 className="text-3xl font-bold tracking-tight veritas-gradient-text">
                  Recuperar acesso
                </h1>
                <p className="text-veritas-silver-dim text-sm max-w-[280px]">
                  Informe seu e-mail cadastrado e enviaremos as instruções para redefinir sua senha.
                </p>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-2">
                <Label htmlFor="email" className="text-veritas-silver/70 ml-1 text-xs uppercase tracking-wider font-semibold">
                  E-mail profissional
                </Label>
                <div className="relative group">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
                  <Input
                    id="email"
                    type="email"
                    placeholder="exemplo@veritas.com.br"
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 h-12 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                  />
                </div>
              </div>

              <Button 
                type="submit" 
                className="w-full h-12 bg-veritas-electric hover:bg-veritas-electric-glow text-veritas-ink font-bold text-base shadow-[0_0_20px_-5px_rgba(101,217,255,0.4)] hover:shadow-[0_0_25px_-2px_rgba(101,217,255,0.5)] transition-all active:scale-[0.98] rounded-xl"
              >
                Enviar instruções
              </Button>
            </form>
          </div>
        ) : (
          <div className="animate-fade-in-up space-y-8 text-center" style={{ animationDelay: '0.2s' }}>
            <div className="flex flex-col items-center space-y-4">
              <div className="w-20 h-20 rounded-full bg-veritas-electric/10 border border-veritas-electric/20 flex items-center justify-center relative">
                <div className="absolute inset-0 bg-veritas-electric/10 rounded-full animate-pulse" />
                <CheckCircle2 className="h-10 w-10 text-veritas-electric relative z-10" />
              </div>

              <div className="space-y-2">
                <h1 className="text-3xl font-bold tracking-tight text-veritas-silver">
                  Verifique seu e-mail
                </h1>
                <p className="text-veritas-silver-dim text-sm max-w-[280px] mx-auto leading-relaxed">
                  Enviamos um link de recuperação para <span className="text-veritas-electric font-medium">{email}</span>. Verifique também sua caixa de spam.
                </p>
              </div>
            </div>

            <div className="pt-4">
              <Button 
                variant="outline"
                onClick={() => navigate({ to: "/login" })}
                className="w-full h-12 border-white/10 text-veritas-silver hover:bg-white/5 hover:border-veritas-electric/30 transition-all rounded-xl font-semibold"
              >
                Voltar ao login
              </Button>
            </div>
          </div>
        )}
      </main>

      {/* Grid Pattern Overlay */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.03]" 
        style={{ 
          backgroundImage: `radial-gradient(circle at 2px 2px, rgba(255,255,255,0.5) 1px, transparent 0)`,
          backgroundSize: '32px 32px' 
        }} 
      />
    </div>
  );
}

