import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { usePWAMode } from "@/hooks/use-pwa-mode";
import { Eye, EyeOff } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";

export const Route = createFileRoute("/login")({
  head: () => ({
    meta: [
      { title: "Login — Veritas Pericial" },
      { name: "description", content: "Acesse seu ambiente profissional no Veritas Pericial." },
      { property: "og:title", content: "Login — Veritas Pericial" },
      { property: "og:description", content: "Acesse seu ambiente profissional no Veritas Pericial." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: LoginPage,
});

function LoginPage() {
  const navigate = useNavigate();
  const { displayMode, requestFullscreen } = usePWAMode();
  const [showPassword, setShowPassword] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (displayMode !== 'browser') {
      await requestFullscreen();
    }
    navigate({ to: "/app" });
  };

  return (
    <div className="veritas-hero-gradient flex min-h-screen w-full flex-col px-6 py-12">
      {/* Background patterns */}
      <div
        className="pointer-events-none absolute inset-0 opacity-[0.03]"
        style={{
          backgroundImage:
            "linear-gradient(rgba(255,255,255,0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.08) 1px, transparent 1px)",
          backgroundSize: "30px 30px",
        }}
      />

      {/* Logo and Header */}
      <div className="animate-fade-in-up flex flex-col items-center text-center">
        <div className="relative mb-6 flex h-16 w-16 items-center justify-center rounded-xl border border-veritas-electric/20 bg-veritas-graphite/60 shadow-[0_0_30px_-10px_rgba(60,130,246,0.3)]">
          <svg viewBox="0 0 48 48" fill="none" className="h-8 w-8 text-veritas-electric">
            <path d="M12 36L24 8L36 36H12Z" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
            <path d="M18 28H30" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
            <circle cx="24" cy="38" r="3" fill="currentColor" />
          </svg>
        </div>
        <h1 className="veritas-gradient-text text-3xl font-bold tracking-tight">Bem-vindo de volta</h1>
        <p className="mt-2 text-veritas-silver-dim/70">Acesse seu ambiente profissional.</p>
      </div>

      {/* Login Form */}
      <form onSubmit={handleLogin} className="animate-fade-in-up mt-12 space-y-6" style={{ animationDelay: "0.1s" }}>
        <div className="space-y-2">
          <Label htmlFor="email">E-mail</Label>
          <Input id="email" type="email" placeholder="nome@exemplo.com" required />
        </div>

        <div className="space-y-2">
          <Label htmlFor="password">Senha</Label>
          <div className="relative">
            <Input 
              id="password" 
              type={showPassword ? "text" : "password"} 
              placeholder="••••••••" 
              required 
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-veritas-silver-dim/60 transition-colors hover:text-veritas-electric"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Checkbox id="remember" />
            <Label htmlFor="remember" className="text-xs cursor-pointer">Lembrar de mim</Label>
          </div>
          <Link 
            to="/forgot-password" 
            className="text-xs font-medium text-veritas-electric hover:text-veritas-electric-glow transition-colors"
          >
            Esqueci minha senha
          </Link>
        </div>

        <Button type="submit" variant="veritas" size="xl" className="w-full">
          Entrar
        </Button>
      </form>

      {/* Divider */}
      <div className="animate-fade-in-up mt-8 flex items-center gap-4" style={{ animationDelay: "0.2s" }}>
        <div className="h-px flex-1 bg-veritas-electric/10" />
        <span className="text-[10px] uppercase tracking-widest text-veritas-silver-dim/40">ou</span>
        <div className="h-px flex-1 bg-veritas-electric/10" />
      </div>

      {/* Social Login */}
      <div className="animate-fade-in-up mt-8" style={{ animationDelay: "0.25s" }}>
        <Button variant="veritas-outline" size="xl" className="w-full gap-3 font-medium">
          <svg className="h-5 w-5" viewBox="0 0 24 24">
            <path
              d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              fill="#4285F4"
            />
            <path
              d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              fill="#34A853"
            />
            <path
              d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"
              fill="#FBBC05"
            />
            <path
              d="M12 5.38c1.62 0 3.06.56 4.21 1.66l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              fill="#EA4335"
            />
          </svg>
          Continuar com Google
        </Button>
      </div>

      {/* Footer */}
      <div className="animate-fade-in-up mt-auto pt-10 text-center" style={{ animationDelay: "0.3s" }}>
        <p className="text-sm text-veritas-silver-dim/60">
          Ainda não possui uma conta?{" "}
          <Link to="/register" className="font-semibold text-veritas-electric hover:text-veritas-electric-glow transition-colors">
            Criar conta
          </Link>
        </p>
      </div>
    </div>
  );
}

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { WifiOff, RefreshCw, Home, ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";

export const Route = createFileRoute("/offline")({
  component: OfflinePage,
});

function OfflinePage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen veritas-hero-gradient flex flex-col items-center justify-center p-6 text-center text-white">
      <div className="absolute inset-0 pointer-events-none opacity-[0.03]" 
        style={{ 
          backgroundImage: `radial-gradient(circle at 2px 2px, rgba(255,255,255,0.5) 1px, transparent 0)`,
          backgroundSize: '32px 32px' 
        }} 
      />

      <div className="relative z-10 space-y-8 max-w-sm animate-fade-in-up">
        <div className="relative mx-auto w-24 h-24 flex items-center justify-center">
          <div className="absolute inset-0 bg-veritas-electric/20 rounded-full blur-2xl animate-pulse-glow" />
          <div className="relative w-20 h-20 rounded-3xl bg-veritas-graphite border border-white/10 flex items-center justify-center shadow-2xl">
            <WifiOff className="w-10 h-10 text-veritas-electric" />
          </div>
        </div>

        <div className="space-y-3">
          <h1 className="text-3xl font-black tracking-tight">Você está offline</h1>
          <p className="text-veritas-silver/60 text-sm leading-relaxed">
            O Veritas continua disponível, mas alguns recursos exigem conexão com a internet.
          </p>
        </div>

        <div className="space-y-3 pt-4">
          <Button 
            className="w-full h-12 bg-veritas-electric hover:bg-veritas-electric-glow text-veritas-ink font-bold gap-2 rounded-xl transition-all active:scale-[0.98]"
            onClick={() => window.location.reload()}
          >
            <RefreshCw className="w-4 h-4" />
            Tentar novamente
          </Button>

          <Button 
            variant="ghost"
            className="w-full h-12 text-veritas-silver hover:bg-white/5 gap-2 rounded-xl"
            onClick={() => navigate({ to: "/" })}
          >
            <Home className="w-4 h-4" />
            Ir para o início
          </Button>
        </div>
      </div>
    </div>
  );
}

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { ChevronRight, ChevronLeft, Shield, Mic, Share2, Zap, CheckCircle2 } from "lucide-react";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/onboarding")({
  head: () => ({
    meta: [
      { title: "Bem-vindo — Veritas Pericial" },
      { name: "description", content: "Conheça o Veritas Pericial." },
      { property: "og:title", content: "Bem-vindo — Veritas Pericial" },
      { property: "og:description", content: "Conheça o Veritas Pericial." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: OnboardingPage,
});

interface Slide {
  title: string;
  description: string;
  icon: React.ReactNode;
  items?: string[];
}

const slides: Slide[] = [
  {
    title: "Sua perícia organizada em um só lugar",
    description: "Gerencie processos, documentos e avaliações com foco na eficiência profissional.",
    icon: <Shield className="w-16 h-16 text-veritas-electric" />,
  },
  {
    title: "Registre entrevistas e informações",
    description: "Capture relatos e dados diretamente no aplicativo com segurança e organização.",
    icon: <Mic className="w-16 h-16 text-veritas-violet" />,
  },
  {
    title: "Toda informação mantém sua origem",
    description: "Documentos, relatos, observações e fontes categorizados para total rastreabilidade.",
    items: ["Documento", "Relato", "Observação", "Fonte"],
    icon: <Share2 className="w-16 h-16 text-blue-400" />,
  },
  {
    title: "Veritas auxilia. O profissional decide.",
    description: "A Veritas organiza, estrutura e verifica. A avaliação e decisão permanecem sob responsabilidade profissional.",
    icon: <Zap className="w-16 h-16 text-amber-400" />,
  },
  {
    title: "Nada é finalizado sem sua revisão",
    description: "Fluxo de trabalho transparente com auditoria e aprovação em cada etapa.",
    items: ["Rascunho", "Auditoria", "Revisão", "Aprovação", "Final"],
    icon: <CheckCircle2 className="w-16 h-16 text-green-400" />,
  },
];

function OnboardingPage() {
  const navigate = useNavigate();
  const [currentSlide, setCurrentSlide] = useState(0);

  const next = () => {
    if (currentSlide < slides.length - 1) {
      setCurrentSlide(currentSlide + 1);
    } else {
      navigate({ to: "/login" });
    }
  };

  const prev = () => {
    if (currentSlide > 0) {
      setCurrentSlide(currentSlide - 1);
    }
  };

  const skip = () => {
    navigate({ to: "/login" });
  };

  const slide = slides[currentSlide];
  if (!slide) return null;

  return (
    <div className="min-h-screen veritas-hero-gradient flex flex-col p-6 text-white relative overflow-hidden">
      {/* Background Glows */}
      <div className="absolute top-[-10%] right-[-20%] w-96 h-96 bg-veritas-electric/10 rounded-full blur-[100px] animate-pulse-glow" />
      <div className="absolute bottom-[-10%] left-[-20%] w-96 h-96 bg-veritas-violet/10 rounded-full blur-[100px] animate-pulse-glow" style={{ animationDelay: '2s' }} />

      {/* Skip Button */}
      <header className="flex justify-end pt-2">
        <Button 
          variant="ghost" 
          className="text-veritas-silver/60 hover:text-veritas-electric transition-colors"
          onClick={skip}
        >
          Pular
        </Button>
      </header>

      {/* Content */}
      <main className="flex-1 flex flex-col items-center justify-center text-center relative z-10 py-12">
        <div key={currentSlide} className="animate-fade-in-up space-y-8 max-w-sm">
          <div className="flex items-center justify-center mb-4">
            <div className="relative">
              <div className="absolute inset-0 bg-white/5 blur-2xl rounded-full" />
              <div className="relative p-6 rounded-3xl bg-veritas-graphite/40 border border-white/5 shadow-2xl backdrop-blur-sm">
                {slide.icon}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <h1 className="text-3xl font-black tracking-tight leading-tight px-4">
              {slide.title}
            </h1>
            <p className="text-veritas-silver/60 text-base px-6">
              {slide.description}
            </p>
          </div>

          {slide.items && (
            <div className="flex flex-wrap justify-center gap-2 pt-2 px-4">
              {slide.items.map((item, i) => (
                <div 
                  key={i} 
                  className="px-3 py-1.5 rounded-full bg-white/5 border border-white/10 text-[10px] font-bold uppercase tracking-wider text-veritas-silver/80"
                >
                  {item}
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="pt-8 pb-4 space-y-8 relative z-10">
        {/* Indicators */}
        <div className="flex justify-center gap-2">
          {slides.map((_, i) => (
            <div 
              key={i}
              className={cn(
                "h-1 rounded-full transition-all duration-300",
                i === currentSlide ? "w-8 bg-veritas-electric" : "w-2 bg-white/10"
              )}
            />
          ))}
        </div>

        <div className="flex items-center justify-between gap-4">
          <Button
            variant="ghost"
            className={cn(
              "flex-1 h-14 rounded-2xl text-veritas-silver hover:bg-white/5 gap-2",
              currentSlide === 0 && "invisible"
            )}
            onClick={prev}
          >
            <ChevronLeft className="w-5 h-5" />
            Voltar
          </Button>

          <Button
            className="flex-[2] h-14 rounded-2xl bg-veritas-electric hover:bg-veritas-electric-glow text-veritas-ink font-bold text-lg gap-2 veritas-button-glow transition-all active:scale-[0.98]"
            onClick={next}
          >
            {currentSlide === slides.length - 1 ? "Começar" : "Próximo"}
            <ChevronRight className="w-5 h-5" />
          </Button>
        </div>
      </footer>

      {/* Grid Pattern */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.03]" 
        style={{ 
          backgroundImage: `radial-gradient(circle at 2px 2px, rgba(255,255,255,0.5) 1px, transparent 0)`,
          backgroundSize: '32px 32px' 
        }} 
      />
    </div>
  );
}

import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { ArrowLeft, Eye, EyeOff, Check, User, Mail, Phone, Lock, ShieldAlert } from "lucide-react";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/register/")({
  component: RegisterIndexPage,
});

function RegisterIndexPage() {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    phone: "",
    password: "",
    confirmPassword: "",
  });

  const passwordRequirements = [
    { label: "Mínimo 8 caracteres", met: formData.password.length >= 8 },
    { label: "Uma letra maiúscula", met: /[A-Z]/.test(formData.password) },
    { label: "Um número", met: /[0-9]/.test(formData.password) },
    { label: "Um caractere especial", met: /[^A-Za-z0-9]/.test(formData.password) },
  ];

  const calculatePasswordStrength = () => {
    const metCount = passwordRequirements.filter(req => req.met).length;
    if (formData.password.length === 0) return 0;
    return (metCount / passwordRequirements.length) * 100;
  };

  const strength = calculatePasswordStrength();
  const strengthColor = 
    strength <= 25 ? "bg-red-500" : 
    strength <= 50 ? "bg-orange-500" : 
    strength <= 75 ? "bg-yellow-500" : 
    "bg-veritas-electric";

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    navigate({ to: "/register/professional" });
  };

  return (
    <div className="min-h-screen veritas-hero-gradient flex flex-col p-6 overflow-hidden relative">
      <div className="absolute top-[-5%] right-[-10%] w-72 h-72 bg-veritas-electric/5 rounded-full blur-3xl" />
      <div className="absolute bottom-[10%] left-[-10%] w-64 h-64 bg-veritas-violet/5 rounded-full blur-3xl" />

      <header className="relative z-10 mb-8 animate-fade-in-up">
        <div className="flex items-center justify-between mb-6">
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={() => navigate({ to: "/login" })}
            className="text-veritas-silver hover:text-veritas-electric hover:bg-white/5 transition-colors rounded-full"
          >
            <ArrowLeft className="h-6 w-6" />
          </Button>
          <div className="text-right">
            <span className="text-veritas-electric text-xs font-bold uppercase tracking-widest">Etapa 1 de 3</span>
            <h1 className="text-xl font-bold text-veritas-silver">Criar sua conta</h1>
          </div>
        </div>
        <div className="space-y-2">
          <Progress value={33} className="h-1.5 bg-white/10" />
          <div className="flex justify-between text-[10px] text-veritas-silver-dim uppercase tracking-tighter font-medium">
            <span className="text-veritas-electric">Pessoal</span>
            <span>Profissional</span>
            <span>Segurança</span>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col max-w-md mx-auto w-full relative z-10 overflow-y-auto pb-12 custom-scrollbar">
        <form onSubmit={handleSubmit} className="space-y-5 animate-fade-in-up">
          <div className="space-y-1.5">
            <Label htmlFor="fullName" className="text-veritas-silver/70 ml-1 text-[10px] uppercase tracking-wider font-bold">
              Nome completo
            </Label>
            <div className="relative group">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
              <Input
                id="fullName"
                placeholder="Seu nome completo"
                required
                className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 h-11 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                value={formData.fullName}
                onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="email" className="text-veritas-silver/70 ml-1 text-[10px] uppercase tracking-wider font-bold">
              E-mail profissional
            </Label>
            <div className="relative group">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
              <Input
                id="email"
                type="email"
                placeholder="exemplo@pericia.com.br"
                required
                className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 h-11 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="phone" className="text-veritas-silver/70 ml-1 text-[10px] uppercase tracking-wider font-bold">
              Telefone
            </Label>
            <div className="relative group">
              <Phone className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
              <Input
                id="phone"
                type="tel"
                placeholder="(00) 00000-0000"
                required
                className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 h-11 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="password" className="text-veritas-silver/70 ml-1 text-[10px] uppercase tracking-wider font-bold">
              Senha
            </Label>
            <div className="relative group">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
              <Input
                id="password"
                type={showPassword ? "text" : "password"}
                placeholder="••••••••"
                required
                className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 pr-10 h-11 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-veritas-silver-dim hover:text-veritas-electric transition-colors"
              >
                {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>

            {formData.password.length > 0 && (
              <div className="space-y-2 px-1 py-1">
                <div className="h-1 w-full bg-white/10 rounded-full overflow-hidden">
                  <div 
                    className={cn("h-full transition-all duration-500", strengthColor)} 
                    style={{ width: `${strength}%` }} 
                  />
                </div>
                <div className="grid grid-cols-2 gap-y-1 gap-x-2">
                  {passwordRequirements.map((req, i) => (
                    <div key={i} className="flex items-center space-x-1">
                      {req.met ? (
                        <Check className="h-3 w-3 text-veritas-electric" />
                      ) : (
                        <div className="h-1 w-1 rounded-full bg-veritas-silver/30 ml-1" />
                      )}
                      <span className={cn(
                        "text-[9px] transition-colors",
                        req.met ? "text-veritas-silver" : "text-veritas-silver/40"
                      )}>
                        {req.label}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="confirmPassword" className="text-veritas-silver/70 ml-1 text-[10px] uppercase tracking-wider font-bold">
              Confirmar senha
            </Label>
            <div className="relative group">
              <ShieldAlert className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-veritas-silver-dim group-focus-within:text-veritas-electric transition-colors" />
              <Input
                id="confirmPassword"
                type={showConfirmPassword ? "text" : "password"}
                placeholder="••••••••"
                required
                className="bg-white/5 border-white/10 text-veritas-silver placeholder:text-veritas-silver/30 pl-10 pr-10 h-11 focus:border-veritas-electric/50 focus:ring-veritas-electric/20 transition-all rounded-xl"
                value={formData.confirmPassword}
                onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-veritas-silver-dim hover:text-veritas-electric transition-colors"
              >
                {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>

          <Button 
            type="submit" 
            className="w-full h-12 bg-veritas-electric hover:bg-veritas-electric-glow text-veritas-ink font-bold text-base shadow-[0_0_20px_-5px_rgba(101,217,255,0.4)] transition-all active:scale-[0.98] rounded-xl mt-4"
          >
            Continuar
          </Button>
        </form>

        <div className="mt-8 text-center">
          <p className="text-veritas-silver-dim text-sm">
            Já possui uma conta?{" "}
            <Link 
              to="/login" 
              className="text-veritas-electric font-semibold hover:text-veritas-electric-glow transition-colors"
            >
              Entrar
            </Link>
          </p>
        </div>
      </main>

      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.03]" 
        style={{ 
          backgroundImage: `radial-gradient(circle at 2px 2px, rgba(255,255,255,0.5) 1px, transparent 0)`,
          backgroundSize: '32px 32px' 
        }} 
      />
    </div>
  );
}

